exam.solution:
def fib(n):
    if n <= 1:
        return n
    return fib(n - 1) + fib(n - 2)

def config(**overrides):
    settings = {"host": "localhost", "port": 8080}
    for key in overrides:
        settings[key] = overrides[key]
    return settings

def best(items, score):
    winner = None
    top = None
    for item in items:
        current = score(item)
        if top is None or current > top:
            top = current
            winner = item
    return winner

def apply_until(value, func, stop, limit=10):
    if limit <= 0 or stop(value):
        return value, 0
    later, steps = apply_until(func(value), func, stop, limit - 1)
    return later, steps + 1
